    // between consecutive elements 
    Collections.sort(rec);
    int d = (int)rec.get(1) - (int)rec.get(0); 
    for (int i = 2; i < n; i++) 
        if (rec.get(i) - rec.get(i - 1) != d) 
            return false;

    return true;
}

